using Biblia.Application.Interfaces;using Biblia.Application.Interfaces.Repositories;using Biblia.Domain.Entities;namespace Biblia.Application.Services;public sealed class MessageReferenceService(IMessageRepository repository):IMessageReferenceService{public Task<IReadOnlyList<MessageReference>> GetAsync(long messageId,CancellationToken cancellationToken=default)=>repository.GetReferencesAsync(messageId,cancellationToken);public async Task<MessageReference>AddAsync(long messageId,long referenceId,long? topicId,string? observation,long? preferredVersionId,CancellationToken cancellationToken=default){var existing=await repository.GetReferencesAsync(messageId,cancellationToken);if(existing.Any(x=>x.ReferenceId==referenceId&&x.TopicId==topicId))throw new InvalidOperationException("Esta referência já está nesta mensagem.");var order=await repository.GetNextReferenceOrderAsync(messageId,cancellationToken);return await repository.AddReferenceAsync(new MessageReference(0,messageId,referenceId,topicId,order,string.IsNullOrWhiteSpace(observation)?null:observation.Trim(),preferredVersionId),cancellationToken);}public Task UpdateAsync(MessageReference reference,CancellationToken cancellationToken=default)=>repository.UpdateReferenceAsync(reference,cancellationToken);public Task DeleteAsync(long id,CancellationToken cancellationToken=default)=>repository.DeleteReferenceAsync(id,cancellationToken);public async Task MoveAsync(long messageId,IReadOnlyList<MessageReference> current,long referenceId,int direction,CancellationToken cancellationToken=default){var index=current.ToList().FindIndex(x=>x.Id==referenceId);var target=index+direction;if(index<0||target<0||target>=current.Count)return;var order=current.Select(x=>x.Id).ToList();(order[index],order[target])=(order[target],order[index]);await repository.ReorderReferencesAsync(messageId,order,cancellationToken);}}
